<template><section class="account-settings"><nav aria-label="Settings"><button v-for="tab in ['Contact information','Notifications','Security']" :key="tab" type="button" :class="{active:section===tab}" @click="section=tab">{{ tab }}</button></nav>
<p v-if="error" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p><p v-if="loading">Loading your account…</p>
<form v-if="data&&section==='Contact information'" @submit.prevent="save"><h2>Your contact information</h2><div class="fields"><label>First name<input v-model="data.first_name" autocomplete="given-name" required maxlength="100"/></label><label>Last name<input v-model="data.last_name" autocomplete="family-name" required maxlength="100"/></label><label>Phone number<input v-model="data.phone" type="tel" autocomplete="tel" placeholder="(719) 555-0100"/></label><label>Time zone<select v-model="data.timezone"><option v-for="z in zones" :key="z.value" :value="z.value">{{z.label}}</option></select></label></div><p>Adding a phone number does not enroll you in texts. Choose Notifications to review your choices and text consent.</p><dl><dt>Sign-in email</dt><dd>{{data.email}}</dd><template v-if="data.username"><dt>Username</dt><dd>{{data.username}}</dd></template><template v-if="data.dateOfBirth"><dt>Date of birth</dt><dd>{{String(data.dateOfBirth).slice(0,10)}}</dd></template></dl><button type="submit" :disabled="busy">{{busy?'Saving…':'Save contact information'}}</button></form>
<div v-if="section==='Notifications'"><h2>Your notifications</h2><p>Choose email and text updates for the profile you are viewing. Text enrollment always requires your permission.</p><button type="button" @click="$emit('notifications')">Manage notification choices</button></div>
<div v-if="section==='Security'"><h2>Account security</h2><p>Manage your password, sign-in methods, and recent sign-in activity.</p><router-link to="/account-security">Open security &amp; sign-in settings →</router-link></div>
</section></template>
<script setup>
import {ref,watch,computed} from 'vue';import api from '../../services/api';import {useAuthStore} from '../../store/auth';
const props=defineProps({agencyId:[Number,String]});defineEmits(['notifications']);const auth=useAuthStore();const data=ref(null),section=ref('Contact information'),loading=ref(false),busy=ref(false),error=ref(''),notice=ref('');
const zones=computed(()=>{const options=[{value:'America/Denver',label:'Mountain time (MDT / MST)'},{value:'America/New_York',label:'Eastern time'},{value:'America/Chicago',label:'Central time'},{value:'America/Los_Angeles',label:'Pacific time'},{value:'America/Phoenix',label:'Arizona time'}];if(data.value?.timezone&&!options.some(z=>z.value===data.value.timezone))options.push({value:data.value.timezone,label:data.value.timezone});return options;});
async function load(){loading.value=true;error.value='';try{const r=await api.get('/guardian-portal/account');data.value={...r.data,timezone:r.data.timezone||'America/Denver'};}catch{error.value='Your account could not be loaded. Please try again.';}finally{loading.value=false;}}
async function save(){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await api.put('/guardian-portal/account',{agencyId:props.agencyId,firstName:data.value.first_name,lastName:data.value.last_name,phone:data.value.phone,timezone:data.value.timezone});if(auth.user)auth.user={...auth.user,first_name:data.value.first_name,last_name:data.value.last_name,firstName:data.value.first_name,lastName:data.value.last_name,timezone:data.value.timezone};notice.value='Contact information saved. Texts still require your permission.';await load();}catch(e){error.value=e.response?.status<500?e.response?.data?.error?.message:'Your changes could not be saved.';}finally{busy.value=false;}}
watch(()=>props.agencyId,load,{immediate:true});
</script>
<style scoped>.account-settings{background:#fff;border:1px solid #dce4ee;border-radius:12px;padding:22px;color:#173451}.account-settings nav{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:24px}button,a{font:inherit;cursor:pointer;color:#16457c}button{padding:12px 16px;border:1px solid #bdcde0;background:white;border-radius:8px}.active,button[type=submit]{background:#16457c;color:white}.fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:18px}label{display:grid;gap:6px}input,select{padding:12px;border:1px solid #aebed2;border-radius:8px;font:inherit;min-width:0;width:100%;box-sizing:border-box}p{line-height:1.6}dl{overflow-wrap:anywhere}dt{font-weight:600}dd{margin:0 0 12px;color:#52647c}[role=alert]{color:#a12727}[role=status]{color:#216047}</style>
